; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

;## ntc_md_vectors ntc_ng_boot
; (the 68k backend requires this section be named ntc_md_vectors - it's the
;  generic "68k vectors + header + start" slot, named after the first 68k target)
; The 68000 vector table at 0, then the Neo Geo cart header / BIOS jump table.
; ;!!NG the real Neo Geo P-ROM header (the "NEO-GEO" marker, the USER and
; interrupt jump entries, the security/soft-DIP area) goes here - stubbed.
			dc.l $00100000          ; initial SSP (top of 68k work RAM) ;!!NG
			dc.l ntc_ng_boot        ; reset PC
			ds.l 62, 0              ; the rest of the 68000 vectors (IRQ, traps) ;!!NG wire VBlank
; ---- the cart header would follow here (ds to $100, the NEO-GEO marker ...) ;!!NG

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:

			; 2: 10 REM classic numbered style
ln_10:

			; 3: 20 N = 1
ln_20:
			dc.l kw_ltov, 1, var_n

			; 4: 30 PRINT N;
ln_30:
			dc.l kw_printint, var_n

			; 5: 40 N = N * 2
ln_40:
			dc.l kw_2x, var_n, var_n

			; 6: 50 IF N < 100 THEN 30
ln_50:
			dc.l kw_scpltvl, var_n, 100
			dc.l kw_goto_iftrue, ln_30

			; 7: 60 PRINT
ln_60:
			dc.l kw_printnl

			; 8: 70 GOSUB 200
ln_70:
			dc.l ln_200_gs

			; 9: 80 END
ln_80:
			dc.l kw_printnl0
			dc.l kw_printstrvar, str0
			dc.l kw_waitkey
			dc.l kw_stop

			; 10: 200 PRINT "in sub" : RETURN
ln_200:
			dc.l kw_printstrvar, str1
			dc.l kw_printnl
			dc.l ln_200_rt

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ln_200_gs:			move.l sp, ln_200_rs
			lea ln_200, sp
			rts
ln_200_rt:			movea.l ln_200_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; ============================================================
; Strings
; ============================================================

str0:			dc.b "Press a key", 0
str1:			dc.b "in sub", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_2x
kw_2x:
			movea.l (sp)+, a0
			move.w (a0), d0
			add.w d0, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_scpltvl ntc_cmp
kw_scpltvl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_slt

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen
ntc_ng_boot:
			move.w #$2700, sr          ; interrupts off during setup
			move.b d0, REG_DIPSW       ; kick the watchdog (any write)     ;!!NG value
			; clear the fix layer, set up the palette and a text font in fix tiles
			jsr ntc_ng_fixclear        ; (below)
			; hand control to the thread - the compiler's start code follows;
			; it sets A7 to the thread and runs. Interrupts get re-enabled there.
			; (ntc_plat_data / screen are pulled in as deps.)
			rts

			even
;## ntc_plat_data ntc_data
ntc_curx:   dc.w 0                     ; fix-layer cursor column (0..39)
ntc_cury:   dc.w 0                     ; row (0..31)
ntc_frames: dc.w 0                     ; frame counter (ntc_plat_ticks)

			even
;## ntc_plat_screen ntc_plat_data ntc_data
; the platform routines are entered with jsr and end with rts (real stack),
; keeping d2-d7 / a2-a6 (the 68k backend's convention).

; ntc_ng_fixaddr - d1.w = the VRAM word address of (ntc_curx, ntc_cury) in the
; fix map. The fix map is column-major: addr = NG_FIXMAP + col*32 + row.  ;!!NG layout
ntc_ng_fixaddr:
			move.w ntc_curx, d1
			lsl.w #5, d1               ; col * 32
			add.w ntc_cury, d1
			add.w #NG_FIXMAP, d1
			rts

; ntc_plat_putc - d0.b = character 32..126: write it as a fix tile, advance
ntc_plat_putc:
			jsr ntc_ng_fixaddr
			move.w d1, REG_VRAMADDR
			move.w #1, REG_VRAMMOD     ; (irrelevant for a single write)
			and.w #$00FF, d0
			; fix tile word = palette<<12 | char code ;!!NG tile numbering / font must be uploaded
			move.w d0, REG_VRAMRW
			addq.w #1, ntc_curx
			cmp.w #40, ntc_curx
			blt.s ntc_pc_done
			jsr ntc_plat_newline
ntc_pc_done:
			rts

; ntc_plat_newline - CR LF: column 0, next row (scroll not done yet) ;!!NG scroll
ntc_plat_newline:
			clr.w ntc_curx
			addq.w #1, ntc_cury
			cmp.w #32, ntc_cury
			blt.s ntc_nl_done
			move.w #31, ntc_cury
ntc_nl_done:
			rts

; ntc_ng_fixclear - blank the whole fix layer (space tile)   ;!!NG space tile index
ntc_ng_fixclear:
			move.w #NG_FIXMAP, REG_VRAMADDR
			move.w #1, REG_VRAMMOD
			move.w #40*32-1, d1
ntc_fc_lp:
			move.w #$0020, REG_VRAMRW
			dbra d1, ntc_fc_lp
			clr.w ntc_curx
			clr.w ntc_cury
			rts

			even
;## ntc_plat_key ntc_plat_data ntc_data
; ntc_plat_scankey - d0.b = a key or 0. Reads P1 (active low). Maps the stick
; to the CPC cursor codes and A/B/C to "A"/"B"/"C"; Start = 13.  ;!!NG bit map
ntc_plat_scankey:
			moveq #0, d0
			move.b REG_P1CNT, d1
			not.b d1                    ; active low -> 1 = pressed
			btst #4, d1                 ; A
			beq.s ntc_sk_b
			moveq #'A', d0
			rts
ntc_sk_b:
			btst #5, d1                 ; B
			beq.s ntc_sk_start
			moveq #'B', d0
			rts
ntc_sk_start:
			move.b REG_STATUS_B, d1
			not.b d1
			btst #0, d1                 ; Start P1
			beq.s ntc_sk_none
			moveq #13, d0
ntc_sk_none:
			rts

; ntc_plat_getkey - wait for a key
ntc_plat_getkey:
			jsr ntc_plat_scankey
			tst.b d0
			beq.s ntc_plat_getkey
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - a cart can't "exit"; spin (a real build returns to the BIOS
; menu / soft-resets) ;!!NG
ntc_plat_exit:
			bra.s ntc_plat_exit


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $FF8000
ntc_ram:
; variables
var_n:			dc.w 0
ln_200_rs:			dc.l 0
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
ntc_bss_size	equ 0
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
